parameters.inputSchema:
{
  "type": "object",
  "properties": {
    "verdict": {
      "type": "string",
      "enum": [
        "pass",
        "partial",
        "fail"
      ]
    },
    "contradicts_reference": {
      "type": "boolean"
    },
    "invented_details": {
      "type": "string",
      "description": "specific claims not in the reference that look invented; empty if none"
    },
    "missing_key_point": {
      "type": "string",
      "description": "important element of the reference the bot left out; empty if none"
    },
    "refused_wrongly": {
      "type": "boolean"
    },
    "reason": {
      "type": "string"
    }
  },
  "required": [
    "verdict",
    "contradicts_reference",
    "invented_details",
    "missing_key_point",
    "refused_wrongly",
    "reason"
  ]
}
